    def chain_merge_construct():
        """Key-centric decomposition: build a per-key chain of that key's
        transactions (ordered by conflict load, hottest first, randomized
        ties), then greedily merge chains like a priority topological sort:
        a txn is ready when all its per-key chain predecessors are placed.
        Among ready txns, candidates are pre-ranked by a proxy (number of
        keys unblocked, accumulated conflict weight) and the winner chosen
        by a short exact lookahead with workload.get_opt_seq_cost. If the
        per-key chains are mutually inconsistent (cycle -> empty ready set),
        fall back to all unplaced txns (conflict-weight ordering), avoiding
        deadlock."""
        keys_of = [set() for _ in range(n)]
        load = [0] * n
        if proxy_ok:
            for i in range(n):
                keys_of[i] = reads[i] | writes[i]
                load[i] = sum(C[i])
        succ = {}
        if proxy_ok:
            key_txns = {}
            for i in range(n):
                for k in keys_of[i]:
                    key_txns.setdefault(k, []).append(i)
            for k, ts in key_txns.items():
                # hottest (highest conflict load) txns first on each key
                order = sorted(ts, key=lambda i: (-load[i], random.random()))
                for a, b in zip(order, order[1:]):
                    succ[(k, a)] = b
        # predecessor count per txn across all its key chains
        preds = [0] * n
        for (k, a), b in succ.items():
            preds[b] += 1
        placed = [False] * n
        seq = []
        score = [0] * n
        for _ in range(n):
            ready = [i for i in range(n) if not placed[i] and preds[i] == 0]
            if not ready:
                # chain inconsistency (cycle): fall back to all unplaced
                ready = [i for i in range(n) if not placed[i]]
            if proxy_ok:
                # proxy: unblock many key-chains, low conflict weight
                ready.sort(key=lambda i: (score[i] - 3 * len(keys_of[i]),
                                          random.random()))
                cands = ready[:6]
            else:
                cands = ready[:8] if len(ready) > 8 else ready
            best, bestc = cands[0], None
            for t in cands:
                c = workload.get_opt_seq_cost(seq + [t])
                if bestc is None or c < bestc:
                    bestc, best = c, t
            seq.append(best)
            placed[best] = True
            # release successors along each of best's key chains
            for k in keys_of[best]:
                b = succ.get((k, best))
                if b is not None and not placed[b]:
                    preds[b] -= 1
            if proxy_ok:
                row = C[best]
                for j in range(n):
                    if not placed[j]:
                        score[j] += row[j]
        return seq
